#!/usr/bin/env python3
"""跨图同对象定位审计 · 完整穿透（真实浏览器，只读）。

走：全书 → 问题/线路 → 星盘 → 罗盘 → 解构面板 → 原文 → 返回
对每个用例记录每一步「对象的规范身份」是否保持同一个（守恒/断链）。

判定口径（可复核）：
  守恒 = 相邻两步引用的**同一个规范 id**；模型层 id（T*）与其来源 id（graph.storylines[].id）
        必须能经 sourceId/唯一名双向对上。
  断链 = 某一步用 name 作键，而该 name 在数据层不是唯一键（多对象共享 / 是他人别名），
        或某一步查不到该 id。

用法：python3 -s /tmp/xgraph_full.py --case collision|auto|main-goal|last-branch|no-quote
"""
import argparse, base64, json, sys, time
from pathlib import Path
ROOT = Path('/Users/carmen/Desktop/星系')
sys.path.insert(0, str(ROOT / 'tests'))
from qa_cinema_wave02_capture import Wave2AuditRunner

READY = '!!(window.CLApp&&CLApp.graph()&&window.CLSky&&window.CLSky.model()&&document.querySelector("#loader.off"))'

CASES = {
    'collision': dict(data='data/cache/2ef47b2ecaa99a67352091d5.json',
                      obj='初代监正', kind='char',
                      note='名字碰撞对象：初代监正（正名）同时是 许平峰 的别名，105 事件；该图 characters 无 id'),
    'auto': dict(data='data/cache/2ef47b2ecaa99a67352091d5.json',
                 obj=None, kind='auto-line', note='真实自动段（autoSegment=true）'),
    'main-goal': dict(data='data/cache/c84e8657afff87043c11ae57.json',
                      obj=None, kind='main-line', note='有目标主线 taskGoalCount=16'),
    'last-branch': dict(data='data/cache/5237714f674230b5d30bf91d.json',
                        obj=None, kind='last-branch', note='末章支线'),
    'no-quote': dict(data='data/cache/5237714f674230b5d30bf91d.json',
                     obj=None, kind='no-quote-task', note='缺引文任务'),
}


class F:
    def __init__(self, base, out):
        self.base = base.rstrip('/'); self.out = Path(out); self.out.mkdir(parents=True, exist_ok=True)
        self.steps = []; self.r = Wave2AuditRunner(width=1440, height=900, dpr=1)

    def ev(self, e, wait=True):
        v = self.r.eval(e, await_promise=wait)
        if isinstance(v, dict) and v.get('__evalError'):
            raise RuntimeError(json.dumps(v, ensure_ascii=False)[:400])
        return v

    def shot(self, n):
        (self.out / n).write_bytes(base64.b64decode(self.r.ws.call('Page.captureScreenshot', format='png')['data']))

    def click(self, sel):
        pt = self.ev('(()=>{var e=document.querySelector(%s);if(!e)return null;var b=e.getBoundingClientRect();if(b.width<1||b.height<1)return null;return [b.x+b.width/2,b.y+b.height/2]})()' % json.dumps(sel), wait=False)
        if not pt: return False
        for t in ('mouseMoved', 'mousePressed', 'mouseReleased'):
            self.r.ws.call('Input.dispatchMouseEvent', type=t, x=pt[0], y=pt[1], button='left', clickCount=1)
        time.sleep(0.5); return True

    def step(self, i, name, probe, note=''):
        rec = {'i': i, 'step': name, 'note': note}
        try: rec['url'] = self.ev('location.href', wait=False)
        except Exception as e: rec['url'] = 'ERR'
        try: rec['dom'] = self.ev(probe, wait=False)
        except Exception as e: rec['dom'] = {'error': str(e)[:300]}
        rec['health'] = self.ev("({jserr:document.body.dataset.jserr||'none',jsrej:document.body.dataset.jsrej||'none'})", wait=False)
        self.shot('%s-%02d-%s.png' % (self.tag, i, name))
        self.steps.append(rec)
        print('  [%02d] %-14s %s' % (i, name, json.dumps(rec['dom'], ensure_ascii=False)[:330]), flush=True)
        return rec


# 每一步都取「当前被引用对象」的规范身份
IDENT = """(()=>{
  var G=CLApp.graph(), S=window.CLSky, M=S.model(), SC=window.CLScene.current||window.CLScene, D=window.CLSkyDeconstruction;
  var nameset={}; G.characters.forEach(function(c){nameset[c.name]=1;});
  var out={};
  /* 图对象命名空间 */
  out.graph = {
    storylines: (G.storylines||[]).map(function(s){return String(s.id!=null?s.id:s.entityId)}),
    charIds: G.characters.map(function(c){return c.id!=null?String(c.id):('NONE:'+c.name)}),
    charsWithId: G.characters.filter(function(c){return c.id!=null||c.entityId!=null}).length,
    charTotal: G.characters.length
  };
  /* 模型对象命名空间（T*）与其来源 */
  out.model = M ? {
    mains: M.mains.map(function(m){return {id:m.id, sourceId:m.sourceId, label:m.label}}),
    lines: M.lines.map(function(l){return {id:l.id, sourceId:l.sourceId, label:l.label}})
  } : null;
  /* 每个模型 id 能否回指到 graph.storylines 的唯一对象（守恒的关键） */
  if (M) {
    var bySrc={}; (G.storylines||[]).forEach(function(s){var k=String(s.id!=null?s.id:s.entityId); (bySrc[k]=bySrc[k]||[]).push(s);});
    out.bridge = M.mains.concat(M.lines).map(function(x){
      var hit = x.sourceId!=null && bySrc[String(x.sourceId)];
      return {modelId:x.id, sourceId:x.sourceId,
              graphHitCount: hit?hit.length:0,
              uniqueBackref: !!(hit && hit.length===1),
              nameUsedAsKey: x.sourceId==null};
    });
  }
  /* 场景层：以 name 为键 */
  var probeName = window.__xjProbe || null;
  if (probeName) {
    var nA=null; try{nA=SC.nodeOf('c:'+probeName)}catch(e){}
    var ch=G.characters.filter(function(c){return c.name===probeName})[0]||null;
    var aliasOwners=G.characters.filter(function(c){return (c.aliases||[]).indexOf(probeName)>=0}).map(function(c){return c.name});
    out.scene = {probe:probeName,
      nodeExists: !!nA, nodeKey: nA?nA.key:null, nodeEc: nA?nA.ec:null,
      canonicalId: ch?(ch.id||null):null,
      nameIsUnique: (ch?1:0)+aliasOwners.length<=1,
      aliasOwners: aliasOwners,
      nodeOfCanonicalId: (ch&&ch.id)?!!SC.nodeOf(String(ch.id)):null};
  }
  /* 罗盘 / 播放器 / 解构 当前身份 */
  try{ var st=S.state(); out.sky={mode:st.mode, compass:st.compass, plot:st.plot, cursor:st.cursor}; }catch(e){}
  try{ out.player={eventId:S.playerState().eventId, eventIndex:S.playerState().eventIndex}; }catch(e){}
  try{ var d=D&&D.state?D.state():null; out.decon=d?{mode:d.mode, focus:d.focus}:null; }catch(e){}
  /* 解构面板：以 name 为键的 people 索引是否有重名/别名歧义 */
  try{
    var ev=G.events[0]||{}, chars=(ev.characters||[]);
    out.sourceChars=chars;
    out.sourceCharsAllKnown=chars.every(function(n){return nameset[n]});
  }catch(e){}
  /*__EXTRA__*/
  return out;
})()"""


def EXTRA(code):
    """把附加探针插到 IDENT 的 return 之前（避免 ASI 把 })() 与下面的 IIFE 连成调用）。"""
    return IDENT.replace('/*__EXTRA__*/', code)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--base', default='http://127.0.0.1:8000')
    ap.add_argument('--case', default='collision')
    ap.add_argument('--out', default='/tmp/castline-shots/xgraph')
    a = ap.parse_args()
    kinds = list(CASES) if a.case == 'all' else [a.case]
    for kind in kinds:
        c = CASES[kind]
        f = F(a.base, a.out); f.tag = kind
        print('=== %s · %s' % (kind, c['note']), flush=True)
        try:
            f.r.start(); f.r.navigate(a.base + '/?sky=1&data=' + c['data'])
            end = time.time() + 220
            while time.time() < end:
                if f.ev(READY, wait=False): break
                time.sleep(0.4)
            else:
                raise RuntimeError('readiness timeout')
            time.sleep(4)

            # 选出本用例的探针对象（脚本内选定，写入 window 供后续步骤复用）
            pick = f.ev("""(()=>{
              var G=CLApp.graph(), M=CLSky.model(), kind=%s;
              var o={kind:kind};
              if(kind==='char'){ o.name=%s; }
              else if(kind==='auto-line'){ var m=M.mains.filter(function(x){return x.autoSegment})[0]; o.modelId=m.id; o.sourceId=m.sourceId; o.label=m.label; }
              else if(kind==='main-line'){ var m2=M.mains.filter(function(x){return x.taskGoalCount>0}).sort(function(a,b){return b.taskGoalCount-a.taskGoalCount})[0]; o.modelId=m2.id; o.sourceId=m2.sourceId; o.label=m2.label; o.taskGoalCount=m2.taskGoalCount; }
              else if(kind==='last-branch'){ var all=M.mains.concat(M.lines).slice().sort(function(a,b){return b.c1-a.c1}); o.modelId=all[0].id; o.sourceId=all[0].sourceId; o.label=all[0].label; o.c1=all[0].c1; o.isMain=M.mains.indexOf(all[0])>=0; }
              else if(kind==='no-quote-task'){ var t=(G.tasks||[]).filter(function(x){return !(x.evidenceQuotes||[]).length})[0]; o.taskId=t?t.id:null; o.entityId=t?t.entityId:null; o.characterId=t?t.characterId:null; o.name=t?t.name:null; o.character=t?t.character:null; o.quote=t?t.quote:null; }
              window.__xjProbe = o.name || null;
              return o;
            })()""" % (json.dumps(c['kind']), json.dumps(c['obj'])), wait=False)
            print('  PICK', json.dumps(pick, ensure_ascii=False), flush=True)

            f.step(0, 'entry', IDENT, '全书入口基线')
            # 1) 全书 → 解构（问题/线路）
            f.click('#skyDecode'); time.sleep(1.2)
            f.step(1, 'deconstruct', IDENT, '全书 → 解构面板')
            f.click('#skyDeconTabLines'); time.sleep(1.0)
            f.step(2, 'lines', IDENT, '解构 → 故事骨架（线路）')
            # 选一条线
            ok = f.click('.sd-line.is-auto' if c['kind'] == 'auto-line' else '.sd-line')
            time.sleep(1.4)
            f.step(3, 'line-focus', IDENT, '点选线路（name→line id 桥接）')
            # 2) 星盘
            f.step(4, 'skychart', IDENT, '解构 → 星盘')
            # 3) 罗盘
            if c['kind'] == 'char':
                f.ev("(()=>{try{CLSky.openCompass(%s);return 1}catch(e){return String(e)}})()" % json.dumps(c['obj']), wait=False)
            else:
                f.ev("(()=>{try{CLSky.openCompass(CLApp.graph().characters[0].name);return 1}catch(e){return String(e)}})()", wait=False)
            time.sleep(2.4)
            f.step(5, 'compass', EXTRA("""
               var c=document.getElementById('skyCompass');
               out.compassDom={open:!!c&&!c.hidden, crumb:(document.getElementById('skyCrumbName')||{}).textContent||null,
                 meta:((document.getElementById('skyCrumbMeta')||{}).textContent||'').slice(0,120)};
            """), '星盘 → 罗盘')
            f.ev("(()=>{try{CLSky.closeCompass();return 1}catch(e){return String(e)}})()", wait=False); time.sleep(1.0)
            # 4) 解构面板（回）
            f.click('#skyDecode'); time.sleep(1.2)
            f.step(6, 'decon-again', IDENT, '罗盘 → 解构面板（同对象？）')
            # 5) 原文
            f.ev("(()=>{try{CLSky.setPlot(true);CLSky.seekEventAt(0);return 1}catch(e){return String(e)}})()", wait=False)
            time.sleep(2.0)
            f.step(7, 'source', EXTRA("""
               var b=document.getElementById('skyStoryBody');
               out.sourceDom={eventId:(function(){try{return CLSky.playerState().eventId}catch(e){return null}})(),
                 text:(b?(b.textContent||'').trim().slice(0,240):null)};
            """), '解构 → 原文')
            # 6) 返回
            f.ev("(()=>{try{CLSky.stop();return 1}catch(e){return String(e)}})()", wait=False); time.sleep(0.8)
            f.click('#skyDecode'); time.sleep(1.0)
            f.step(8, 'return', EXTRA("""
               var p=document.getElementById('skyDeconPanel');
               out.returnDom={panelOpen:!!p&&!p.hidden,
                 focusedLineId:(p&&p.querySelector('.sd-line.is-focus'))?p.querySelector('.sd-line.is-focus').getAttribute('data-line-id'):null};
            """), '原文 → 返回')
        except Exception as e:
            print('  CASE ERROR', str(e)[:300], flush=True)
            f.steps.append({'error': str(e)[:300]})
        finally:
            (f.out / ('full-%s.json' % kind)).write_text(json.dumps(
                {'case': kind, 'note': c['note'], 'data': c['data'], 'pick': c.get('obj'), 'steps': f.steps},
                ensure_ascii=False, indent=2), encoding='utf-8')
            try: f.r.close()
            except Exception: pass
    return 0


if __name__ == '__main__':
    sys.exit(main())

