#!/usr/bin/env python3
"""决定性探针：跨图键用 character.name 是否真的造成【用户可见】错位。

判据（三条同时成立才算真缺陷）：
 A. 数据层存在两个不同规范对象（不同 id），它们共享同一个 name 键；
    或某对象的规范 id 存在、但名字不是唯一键。
 B. 运行时 nodeByKey / byId 等以 name 为键的映射，把用户操作解析到**错误对象**。
 C. 该错误在真实交互路径上可达，且投影到屏幕上指向另一个对象的位置（可截图佐证）。

只读；不改任何源码。
"""
import argparse, base64, json, sys, time
from pathlib import Path
ROOT = Path('/Users/carmen/Desktop/星系')
sys.path.insert(0, str(ROOT / 'tests'))
from qa_cinema_wave02_capture import Wave2AuditRunner

READY = '!!(window.CLApp&&CLApp.graph()&&window.CLSky&&window.CLSky.model()&&document.querySelector("#loader.off"))'


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--base', default='http://127.0.0.1:8000')
    ap.add_argument('--data', default='data/cache/0031d168fc78500314ede8fb.json')
    ap.add_argument('--out', default='/tmp/castline-shots/xgraph')
    a = ap.parse_args()
    out = Path(a.out); out.mkdir(parents=True, exist_ok=True)
    r = Wave2AuditRunner(width=1440, height=900, dpr=1)

    def ev(e, wait=True):
        v = r.eval(e, await_promise=wait)
        if isinstance(v, dict) and v.get('__evalError'):
            raise RuntimeError(json.dumps(v, ensure_ascii=False)[:500])
        return v

    results = {}
    try:
        r.start()
        r.navigate(a.base + '/?sky=1&data=' + a.data)
        end = time.time() + 220
        while time.time() < end:
            if ev(READY, wait=False):
                break
            time.sleep(0.4)
        else:
            print('READY-TIMEOUT'); return 2
        time.sleep(5)

        # ---- A. 数据层：名字键是否唯一 ----
        results['A_data_identity'] = ev("""(()=>{
          var G=CLApp.graph();
          var byName={},dupName=[],noId=[];
          G.characters.forEach(function(c){
            var k=String(c.name);
            if(byName[k]) dupName.push(k); else byName[k]=c;
            if(c.id==null&&c.entityId==null) noId.push(k);
          });
          return {characters:G.characters.length, dupNameCount:dupName.length, dupNames:dupName.slice(0,10),
                  noCanonicalId:noId.length,
                  idOk:G.characters.filter(function(c){return c.id!=null}).length,
                  sampleIds:G.characters.slice(0,3).map(function(c){return {name:c.name,id:c.id,entityId:c.entityId}})};
        })()""", wait=False)

        # ---- B1. nodeByKey 是否用 name；同一个名字解析到几个场景节点 ----
        results['B1_nodeKey'] = ev("""(()=>{
          var G=CLApp.graph(), S=window.CLScene.current||window.CLScene;
          var mism=[], multi=[], resolved=0, unresolved=0;
          G.characters.forEach(function(c){
            var n=null; try{ n=S.nodeOf('c:'+c.name); }catch(e){}
            if(!n){ unresolved++; mism.push(c.name); return; }
            resolved++;
            if(n.key && n.key!=='c:'+c.name) multi.push({name:c.name,nodeKey:n.key});
          });
          /* 关键判据：场景节点的 key 是否等于规范 id（应然）还是 name（实然） */
          var keys=[]; try{ keys=S.nodes?S.nodes().slice(0,5).map(function(n){return n.key}):[]; }catch(e){}
          return {resolvedByName:resolved, unresolvedByName:unresolved, unresolvedSample:mism.slice(0,8),
                  nodeKeyIsNameSample:multi.slice(0,5), sceneNodeKeysSample:keys};
        })()""", wait=False)

        # ---- B2. 规范 id -> 节点 是否可用（若 id 是规范键，应该也能查到） ----
        results['B2_idLookup'] = ev("""(()=>{
          var G=CLApp.graph(), S=window.CLScene.current||window.CLScene;
          var byId=0, byIdNull=0, sample=[];
          G.characters.slice(0,60).forEach(function(c){
            var n=null; try{ n=S.nodeOf(String(c.id)); }catch(e){}
            if(n) byId++; else { byIdNull++; if(sample.length<5) sample.push({id:c.id,name:c.name}); }
          });
          return {byCanonicalIdResolved:byId, byCanonicalIdNull:byIdNull, nullSample:sample};
        })()""", wait=False)

        # ---- B3. 别名（非正名）能否解析：事件用的是别名还是正名 ----
        results['B3_alias'] = ev("""(()=>{
          var G=CLApp.graph(), S=window.CLScene.current||window.CLScene;
          var rows=[];
          G.characters.forEach(function(c){
            (c.aliases||[]).slice(0,3).forEach(function(al){
              if(rows.length>=40) return;
              var n=null; try{ n=S.nodeOf('c:'+al); }catch(e){}
              var evN=G.events.filter(function(e){return (e.characters||[]).indexOf(al)>=0}).length;
              var evC=G.events.filter(function(e){return (e.characters||[]).indexOf(c.name)>=0}).length;
              rows.push({name:c.name, alias:al, aliasResolvesToNode:!!n, aliasEventMentions:evN, canonicalEventMentions:evC});
            });
          });
          return {tested:rows.length,
                  aliasResolvedButNotCanonical:rows.filter(function(x){return x.aliasResolvesToNode&&x.aliasEventMentions>0}).length,
                  aliasEventMentionsTotal:rows.reduce(function(a,x){return a+x.aliasEventMentions},0),
                  canonicalEventMentionsTotal:rows.reduce(function(a,x){return a+x.canonicalEventMentions},0),
                  sample:rows.slice(0,8)};
        })()""", wait=False)

        # ---- C. 端到端：用一个「名字」驱动的定位，看落在哪个对象上 ----
        results['C_locate'] = ev("""(()=>{
          var G=CLApp.graph(), S=window.CLSky, SC=window.CLScene.current||window.CLScene;
          var probe=null;
          for(var i=0;i<G.characters.length;i++){
            var c=G.characters[i];
            if((c.aliases||[]).length){ probe=c; break; }
          }
          if(!probe) return {skipped:'no aliased character'};
          var alias=probe.aliases[0];
          var nodeByAlias=null, nodeByCanon=null;
          try{ nodeByAlias=SC.nodeOf('c:'+alias); }catch(e){}
          try{ nodeByCanon=SC.nodeOf('c:'+probe.name); }catch(e){}
          return {probeName:probe.name, probeId:probe.id, probeAlias:alias,
                  nodeByAliasIsCanonical: nodeByAlias===nodeByCanon,
                  aliasResolves: !!nodeByAlias, canonicalResolves: !!nodeByCanon,
                  aliasEventMentions: G.events.filter(function(e){return (e.characters||[]).indexOf(alias)>=0}).length};
        })()""", wait=False)

        (out / 'namekey-verdict.json').write_text(json.dumps(results, ensure_ascii=False, indent=2), encoding='utf-8')
        print(json.dumps(results, ensure_ascii=False, indent=2)[:6000])
        h = ev("({jserr:document.body.dataset.jserr||'none',jsrej:document.body.dataset.jsrej||'none'})", wait=False)
        print('HEALTH:', h)
    finally:
        try:
            r.close()
        except Exception:
            pass
    return 0


if __name__ == '__main__':
    sys.exit(main())

