#!/usr/bin/env python3
"""碰撞对象端到端可见性探针：初代监正（正名 + 许平峰的别名，105 个事件）。

问题：跨图键用 character.name。当 token 既是 A 的正名又是 B 的别名时，
app.js 刻意「不归并」（ambiguous）。此时：
  - 事件表里保留 token 原样，但 `e.characters` 会被过滤成「必须在 by[] 里」；
  - 罗盘/搜索以 name 为键找角色；
  - 场景节点以 'c:'+name 为键。
要测的是：用户点「初代监正」时，落到的到底是哪个对象，事件数是多少，页面上写的是谁。
只读。
"""
import argparse, base64, json, sys, time
from pathlib import Path
ROOT = Path('/Users/carmen/Desktop/星系')
sys.path.insert(0, str(ROOT / 'tests'))
from qa_cinema_wave02_capture import Wave2AuditRunner

READY = '!!(window.CLApp&&CLApp.graph()&&window.CLSky&&window.CLSky.model()&&document.querySelector("#loader.off"))'


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--base', default='http://127.0.0.1:8000')
    ap.add_argument('--data', default='data/cache/2ef47b2ecaa99a67352091d5.json')
    ap.add_argument('--out', default='/tmp/castline-shots/xgraph')
    a = ap.parse_args()
    out = Path(a.out); out.mkdir(parents=True, exist_ok=True)
    r = Wave2AuditRunner(width=1440, height=900, dpr=1)
    rep = {}

    def ev(e, wait=True):
        v = r.eval(e, await_promise=wait)
        if isinstance(v, dict) and v.get('__evalError'):
            raise RuntimeError(json.dumps(v, ensure_ascii=False)[:400])
        return v

    def shot(n):
        (out / n).write_bytes(base64.b64decode(r.ws.call('Page.captureScreenshot', format='png')['data']))

    try:
        r.start()
        r.navigate(a.base + '/?sky=1&data=' + a.data)
        end = time.time() + 220
        while time.time() < end:
            if ev(READY, wait=False):
                break
            time.sleep(0.4)
        else:
            print('READY-TIMEOUT'); return 2
        time.sleep(4)

        # 1) 数据层：boundary 之后，token 的归属与计数
        rep['boundary'] = ev("""(()=>{
          var G=CLApp.graph(), q=G.meta&&G.meta.quality||{};
          function ch(n){return G.characters.filter(function(c){return c.name===n})[0]||null;}
          function evc(n){return G.events.filter(function(e){return (e.characters||[]).indexOf(n)>=0}).length;}
          var A=ch('初代监正'), B=ch('许平峰');
          return {alias_conflicts:q.alias_conflicts, ambiguous_alias_tokens:q.ambiguous_alias_tokens,
                  attribution_pending:q.attribution_pending, ambiguous_alias_mentions:q.ambiguous_alias_mentions,
                  A_exists:!!A, A_aliases:A?A.aliases:null, A_events:evc('初代监正'),
                  B_exists:!!B, B_aliases:B?B.aliases:null, B_events:evc('许平峰'),
                  /* 109 个「初代监正」事件被算给谁？两边都算 = 双重归属 */
                  attributionQueue:(G.meta&&G.meta.attributionQueue||[]).filter(function(x){return (x.tokens||[]).indexOf('初代监正')>=0}).slice(0,3)};
        })()""", wait=False)

        # 2) 场景层：两个 key 解析到哪个节点（是否同一个对象）
        rep['scene_nodes'] = ev("""(()=>{
          var S=window.CLScene.current||window.CLScene;
          function n(k){try{return S.nodeOf(k)}catch(e){return null}}
          var a=n('c:初代监正'), b=n('c:许平峰');
          return {byName_A: a?{key:a.key,tier:a.tier,ec:a.ec,w:Math.round(a.w),label:a.label}:null,
                  byName_B: b?{key:b.key,tier:b.tier,ec:b.ec,w:Math.round(b.w),label:b.label}:null,
                  sameNode: a===b,
                  byCanonicalId_A: !!n('ch_dummy')};
        })()""", wait=False)

        # 3) 罗盘：用户点「初代监正」看到谁
        rep['compass_open_A'] = ev("""(()=>{
          var ok=false, err=null;
          try{ ok = CLSky.openCompass('初代监正'); }catch(e){ err=String(e); }
          return {ok:ok, err:err, crumb: (document.getElementById('skyCrumbName')||{}).textContent||null,
                  meta: (document.getElementById('skyCrumbMeta')||{}).textContent||null};
        })()""", wait=False)
        time.sleep(2.5)
        rep['compass_settled_A'] = ev("""(()=>{
          var c=document.getElementById('skyCompass');
          return {state: CLSky.state().mode, compassName: CLSky.state().compass,
                  crumb:(document.getElementById('skyCrumbName')||{}).textContent||null,
                  meta:(document.getElementById('skyCrumbMeta')||{}).textContent||null,
                  bodyKeys:(function(){try{var m=CLSkyDeep&&CLSkyDeep.snapshot?CLSkyDeep.snapshot():null;return m?Object.keys(m):null}catch(e){return null}})()};
        })()""", wait=False)
        shot('collision-A-初代监正-compass.png')

        # 4) 同一个罗盘里再点「许平峰」——两者 event 数应不同
        rep['compass_open_B'] = ev("(()=>{var ok=false,err=null;try{ok=CLSky.openCompass('许平峰')}catch(e){err=String(e)}return {ok:ok,err:err}})()", wait=False)
        time.sleep(2.5)
        rep['compass_settled_B'] = ev("""(()=>({crumb:(document.getElementById('skyCrumbName')||{}).textContent||null,
            meta:(document.getElementById('skyCrumbMeta')||{}).textContent||null, compassName:CLSky.state().compass}))()""", wait=False)
        shot('collision-B-许平峰-compass.png')

        # 5) 搜索：输入「初代监正」返回哪些候选（是否把两个对象混在一起）
        rep['search'] = ev("""(()=>{
          var G=CLApp.graph();
          var rows=[];
          try{
            if(window.CLSkySearch && CLSkySearch.__probe){ rows = CLSkySearch.__probe('初代监正'); }
          }catch(e){}
          /* 回退：直接查模型里以该 token 为 name/alias 的角色数 */
          var byName=G.characters.filter(function(c){return c.name==='初代监正'});
          var byAlias=G.characters.filter(function(c){return (c.aliases||[]).indexOf('初代监正')>=0});
          return {directSearch:rows, charactersNamedToken:byName.map(function(c){return {name:c.name,role:c.role}}),
                  charactersWithTokenAsAlias:byAlias.map(function(c){return {name:c.name,role:c.role}}),
                  tokenIsMultiOwned: (byName.length+byAlias.length)>1};
        })()""", wait=False)

        # 6) 原文：从「初代监正」事件读原文，看人物归属
        rep['source'] = ev("""(()=>{
          var G=CLApp.graph();
          var i=G.events.findIndex(function(e){return (e.characters||[]).indexOf('初代监正')>=0});
          if(i<0) return {none:true};
          CLSky.setPlot(true); CLSky.seekEventAt(i);
          return {eventIndex:i, eventId:G.events[i].id, title:G.events[i].title, quote:G.events[i].quote,
                  characters:G.events[i].characters};
        })()""", wait=False)
        time.sleep(2.0)
        rep['source_settled'] = ev("""(()=>{
          var b=document.getElementById('skyStoryBody');
          return {eventId:CLSky.playerState().eventId, text:(b?(b.textContent||'').trim().slice(0,400):null)};
        })()""", wait=False)
        shot('collision-C-source.png')

        (out / 'collision-verdict.json').write_text(json.dumps(rep, ensure_ascii=False, indent=2), encoding='utf-8')
        print(json.dumps(rep, ensure_ascii=False, indent=2))
        print('HEALTH:', ev("({jserr:document.body.dataset.jserr||'none',jsrej:document.body.dataset.jsrej||'none'})", wait=False))
    finally:
        try:
            r.close()
        except Exception:
            pass
    return 0


if __name__ == '__main__':
    sys.exit(main())

