#!/usr/bin/env python3
"""别名键 vs 规范 id 键：用户可见差异的决定性测试（只读）。

背景（已证）：ch_ 规范 id = hash({name})，所以「用 name 当键」在**正名唯一**时
与「用规范 id 当键」信息等价 —— 这就是四个用例都不断链的原因。
真正会分叉的场景：**别名 token**。别名不是任何对象的 name，因此：
  - 以 name 为键的入口（openCompass / nodeOf('c:'+token)）查不到；
  - 若别名恰好又是**另一个人的正名**（初代监正/许平峰），则解析到**另一个对象**。
本脚本测这两类路径在真实 UI 上的表现，并截图。
"""
import argparse, base64, json, sys, time
from pathlib import Path
ROOT = Path('/Users/carmen/Desktop/星系')
sys.path.insert(0, str(ROOT / 'tests'))
from qa_cinema_wave02_capture import Wave2AuditRunner

READY = '!!(window.CLApp&&CLApp.graph()&&window.CLSky&&window.CLSky.model()&&document.querySelector("#loader.off"))'
DATA = 'data/cache/2ef47b2ecaa99a67352091d5.json'


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--base', default='http://127.0.0.1:8000')
    ap.add_argument('--out', default='/tmp/castline-shots/xgraph')
    a = ap.parse_args()
    out = Path(a.out); out.mkdir(parents=True, exist_ok=True)
    r = Wave2AuditRunner(width=1440, height=900, dpr=1)
    rep = {}

    def ev(e, wait=True):
        v = r.eval(e, await_promise=wait)
        if isinstance(v, dict) and v.get('__evalError'):
            raise RuntimeError(json.dumps(v, ensure_ascii=False)[:400])
        return v

    def shot(n):
        (out / n).write_bytes(base64.b64decode(r.ws.call('Page.captureScreenshot', format='png')['data']))

    try:
        r.start()
        r.navigate(a.base + '/?sky=1&data=' + DATA)
        end = time.time() + 220
        while time.time() < end:
            if ev(READY, wait=False):
                break
            time.sleep(0.4)
        else:
            print('READY-TIMEOUT'); return 2
        time.sleep(4)

        # 1) 三种 token 的静态解析能力
        rep['resolve_matrix'] = ev("""(()=>{
          var G=CLApp.graph(), SC=window.CLScene.current||window.CLScene;
          var cases=[
            {t:'许七安', why:'正名（唯一）'},
            {t:'初代监正', why:'正名，但同为 许平峰 的别名'},
            {t:'监正', why:'初代监正 的别名（也是他人别名？）'},
            {t:'小白狐', why:'许铃音 的别名，且自己是独立角色正名'},
            {t:'七哥', why:'许七安 的纯别名（无独立角色）'},
            {t:'国师', why:'洛玉衡/许平峰 的共同别名（无独立角色）'}
          ];
          return cases.map(function(c){
            var byName=G.characters.filter(function(x){return x.name===c.t}).map(function(x){return {name:x.name,id:x.id}});
            var byAlias=G.characters.filter(function(x){return (x.aliases||[]).indexOf(c.t)>=0}).map(function(x){return {name:x.name,id:x.id}});
            var n=null; try{n=SC.nodeOf('c:'+c.t)}catch(e){}
            return {token:c.t, why:c.why,
                    charactersNamedToken:byName, charactersOwningTokenAsAlias:byAlias,
                    nameKeyResolves:!!n, nameKeyTarget: n?(n.data&&n.data.name):null,
                    nameKeyEc: n?n.ec:null,
                    owners:(byName.length+byAlias.length),
                    verdict: (byName.length===1&&byAlias.length===0)?'unique-name'
                           : (byName.length===0&&byAlias.length>0)?'alias-only'
                           : (byName.length===1&&byAlias.length>0)?'AMBIGUOUS(name+alias)'
                           : (byName.length===0&&byAlias.length===0)?'no-such-token'
                           : (byName.length===0&&byAlias.length>1)?'multi-alias' : 'other'};
          });
        })()""", wait=False)

        # 2) openCompass 对每个 token 的实际行为（用户点搜索结果 = 走这条）
        for tok in ['许七安', '初代监正', '监正', '七哥', '国师', '小白狐']:
            rep['compass_' + tok] = ev("""(()=>{
              var res=null;
              try{ res = CLSky.openCompass(%s); }catch(e){ return {token:%s, threw:String(e)}; }
              var crumb=(document.getElementById('skyCrumbName')||{}).textContent||null;
              var meta=(document.getElementById('skyCrumbMeta')||{}).textContent||null;
              return {token:%s, ok:res, crumb:crumb, meta:(meta||'').slice(0,90), state:CLSky.state().compass};
            })()""" % (json.dumps(tok), json.dumps(tok), json.dumps(tok)), wait=False)
            time.sleep(1.6)
            if tok in ('初代监正', '监正', '七哥'):
                shot('alias-%s-compass.png' % tok)
            if ev('CLSky.state().mode', wait=False) == 'compass':
                ev("(()=>{try{CLSky.closeCompass();return 1}catch(e){return String(e)}})()", wait=False)
                time.sleep(1.0)

        # 3) 搜索面板：输入别名时给出什么候选（用户可见入口）
        rep['search_alias'] = ev("""(()=>{
          var G=CLApp.graph();
          var rows=[];
          ['初代监正','监正','七哥','小白狐'].forEach(function(q){
            var hits=G.characters.filter(function(c){
              return c.name.indexOf(q)>=0 || (c.aliases||[]).some(function(al){return al.indexOf(q)>=0});
            }).map(function(c){return {name:c.name,id:c.id,matchedAsName:c.name.indexOf(q)>=0,
                                       matchedAsAlias:(c.aliases||[]).filter(function(al){return al.indexOf(q)>=0})}});
            rows.push({q:q, n:hits.length, hits:hits.slice(0,6)});
          });
          return rows;
        })()""", wait=False)

        (out / 'alias-verdict.json').write_text(json.dumps(rep, ensure_ascii=False, indent=2), encoding='utf-8')
        print(json.dumps(rep, ensure_ascii=False, indent=2)[:7000])
        print('HEALTH:', ev("({jserr:document.body.dataset.jserr||'none',jsrej:document.body.dataset.jsrej||'none'})", wait=False))
    finally:
        try: r.close()
        except Exception: pass
    return 0


if __name__ == '__main__':
    sys.exit(main())

