#!/usr/bin/env python3
"""深链别名端到端：真实 UI 路径（预演实验室 #sky= 恢复）对别名 token 的行为。

这是「跨图键用 name 而非规范 id」唯一能真正走到用户眼前的路径：
  分享链接 / 返回点把 compass 写成别名 token →
  sky-lab 的 validate() 用 c.name 比对 → 别名不匹配任何 name →
  应当拒绝并给出「深链对象不在当前作品」而不是**静默落到 0 或落到别人**。
本脚本对 name / 正名 / 别名 / 共同别名四类 token 各跑一次，记录落点与提示，并截图。
只读。
"""
import argparse, base64, json, sys, time
from pathlib import Path
ROOT = Path('/Users/carmen/Desktop/星系')
sys.path.insert(0, str(ROOT / 'tests'))
from qa_cinema_wave02_capture import Wave2AuditRunner

READY = '!!(window.CLApp&&CLApp.graph()&&window.CLSky&&window.CLSky.model()&&document.querySelector("#loader.off"))'
DATA = 'data/cache/2ef47b2ecaa99a67352091d5.json'


def enc(o):
    b = json.dumps(o, separators=(',', ':'), ensure_ascii=False).encode()
    return base64.b64encode(b).decode().replace('+', '-').replace('/', '_').rstrip('=')


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--base', default='http://127.0.0.1:8000')
    ap.add_argument('--out', default='/tmp/castline-shots/xgraph')
    a = ap.parse_args()
    out = Path(a.out); out.mkdir(parents=True, exist_ok=True)
    r = Wave2AuditRunner(width=1440, height=900, dpr=1)
    rep = {'cases': []}

    def ev(e, wait=True):
        v = r.eval(e, await_promise=wait)
        if isinstance(v, dict) and v.get('__evalError'):
            raise RuntimeError(json.dumps(v, ensure_ascii=False)[:400])
        return v

    try:
        r.start()
        for tok, why in [('许七安', '正名（唯一）'), ('初代监正', '正名 + 他人别名'),
                         ('监正', '纯别名'), ('七哥', '纯别名（唯一 owner）'),
                         ('国师', '共同别名（两个 owner）')]:
            snap = {'v': 1, 'group': None, 'plot': False, 'compass': tok, 'cursor': None, 'line': None}
            url = a.base + '/?sky=1&data=' + DATA + '#sky=' + enc({'v': 1, 'frame': 'C0', 'snap': snap, 'modes': None})
            r.navigate(url)
            t0 = time.time()
            while time.time() - t0 < 200:
                if ev(READY, wait=False):
                    break
                time.sleep(0.4)
            time.sleep(5)
            rec = {'token': tok, 'why': why, 'url_hash_token': tok}
            rec['result'] = ev("""(()=>{
              var st=CLSky.state(), crumb=(document.getElementById('skyCrumbName')||{}).textContent||null;
              /* 预演面板的提示文本 = 用户能看到的解释 */
              var lab=document.getElementById('skyLab')||document.querySelector('.sky-lab');
              var note=null;
              if(lab){ var n=lab.querySelector('.sl-note,.lab-note,[data-lab-note],.note'); note=n?(n.textContent||'').trim().slice(0,160):null; }
              var anyNote=Array.prototype.slice.call(document.querySelectorAll('[class*=note]'))
                  .map(function(e){return (e.textContent||'').trim()}).filter(function(t){return t&&t.length<200}).slice(0,6);
              return {mode:st.mode, compass:st.compass, crumb:crumb,
                      crumbMeta:((document.getElementById('skyCrumbMeta')||{}).textContent||'').slice(0,90),
                      labOpen: !!lab && !lab.hidden,
                      notes:anyNote};
            })()""", wait=False)
            # 该 token 应当落到的对象（数据层真值）
            rec['expected'] = ev("""(()=>{
              var G=CLApp.graph(), t=%s;
              var named=G.characters.filter(function(c){return c.name===t}).map(function(c){return {name:c.name,id:c.id}});
              var alias=G.characters.filter(function(c){return (c.aliases||[]).indexOf(t)>=0}).map(function(c){return {name:c.name,id:c.id}});
              return {named:named, aliasOwners:alias};
            })()""" % json.dumps(tok), wait=False)
            rec['health'] = ev("({jserr:document.body.dataset.jserr||'none',jsrej:document.body.dataset.jsrej||'none'})", wait=False)
            (out / ('deeplink-%s.png' % tok)).write_bytes(
                base64.b64decode(r.ws.call('Page.captureScreenshot', format='png')['data']))
            rep['cases'].append(rec)
            print('%-8s %-22s -> mode=%-12s compass=%-10s crumb=%-10s' % (
                tok, why, rec['result'].get('mode'), rec['result'].get('compass'), rec['result'].get('crumb')), flush=True)
            print('        notes=%s' % json.dumps(rec['result'].get('notes'), ensure_ascii=False)[:300], flush=True)
        (out / 'deeplink-verdict.json').write_text(json.dumps(rep, ensure_ascii=False, indent=2), encoding='utf-8')
    finally:
        try: r.close()
        except Exception: pass
    return 0


if __name__ == '__main__':
    sys.exit(main())

