#!/usr/bin/env python3
"""跨图同对象定位审计 · 真实浏览器全路径驱动（只读）。

路径：全书 → 问题/线路 → 星盘 → 罗盘 → 解构面板 → 原文 → 返回
每一步记录：URL / 选择器 / DOM 里承载对象的 id 或属性 / 该对象在数据层的规范 id。
断链判定：同一对象在相邻两步的规范 id 不同，或 DOM 里查无此 id。

用法：
  python3 -s /tmp/xgraph_journey.py --case auto --out /tmp/castline-shots/xgraph
"""
import argparse, base64, json, sys, time
from pathlib import Path
ROOT = Path('/Users/carmen/Desktop/星系')
sys.path.insert(0, str(ROOT / 'tests'))
from qa_cinema_wave02_capture import Wave2AuditRunner

# ---------- 四个用例：真实数据里各挑一条 ----------
CASES = {
    # 1) 真实自动段：大奉 8/8 主线全是 autoSegment（objective=none），无 tasks
    'auto': dict(data='data/cache/2ef47b2ecaa99a67352091d5.json',
                 note='真实自动段（autoSegment=true，objective=none）'),
    # 2) 有目标主线：西游 T1 有 16 个已声明目标任务
    'main-goal': dict(data='data/cache/c84e8657afff87043c11ae57.json',
                      note='有目标主线（taskGoalCount=16）'),
    # 3) 末章支线：三国 T22 主线收在 112 回 + 末段支线
    'last-branch': dict(data='data/cache/5237714f674230b5d30bf91d.json',
                        note='末章支线（c1 最大）'),
    # 4) 缺引文任务：三国 30/54 任务无 evidenceQuotes
    'no-quote': dict(data='data/cache/5237714f674230b5d30bf91d.json',
                     note='缺引文任务（evidenceQuotes 为空）'),
}

READY = '!!(window.CLApp&&CLApp.graph()&&window.CLSky&&window.CLSky.model()&&document.querySelector("#loader.off"))'


class Journey:
    def __init__(self, base, out):
        self.base = base.rstrip('/')
        self.out = Path(out)
        self.out.mkdir(parents=True, exist_ok=True)
        self.steps = []
        self.console = []
        self.r = Wave2AuditRunner(width=1440, height=900, dpr=1)

    def ev(self, expr, wait=True):
        v = self.r.eval(expr, await_promise=wait)
        if isinstance(v, dict) and v.get('__evalError'):
            raise RuntimeError(json.dumps(v, ensure_ascii=False)[:600])
        return v

    def shot(self, name):
        p = self.out / (name + '.png')
        p.write_bytes(base64.b64decode(self.r.ws.call('Page.captureScreenshot', format='png')['data']))
        return p.name

    def click(self, sel):
        pt = self.ev('(()=>{var e=document.querySelector(%s);if(!e)return null;var b=e.getBoundingClientRect();'
                     'if(b.width<1||b.height<1)return null;return [b.x+b.width/2,b.y+b.height/2]})()'
                     % json.dumps(sel), wait=False)
        if not pt:
            return False
        for t in ('mouseMoved', 'mousePressed', 'mouseReleased'):
            self.r.ws.call('Input.dispatchMouseEvent', type=t, x=pt[0], y=pt[1], button='left', clickCount=1)
        time.sleep(0.45)
        return True

    def health(self):
        return self.ev("({jserr:document.body.dataset.jserr||'none',jsrej:document.body.dataset.jsrej||'none',"
                       "cltest:document.body.dataset.cltest||''})", wait=False)

    def step(self, n, name, selector, probe, note=''):
        rec = {'n': n, 'step': name, 'selector': selector, 'note': note}
        try:
            rec['url'] = self.ev('location.href', wait=False)
        except Exception as e:
            rec['url'] = 'ERR:' + str(e)[:100]
        try:
            rec['dom'] = self.ev(probe, wait=False)
        except Exception as e:
            rec['dom'] = {'error': str(e)[:400]}
        rec['health'] = self.health()
        rec['shot'] = self.shot('%02d-%s' % (n, name))
        self.steps.append(rec)
        print('  [%02d] %-16s %s' % (n, name, json.dumps(rec['dom'], ensure_ascii=False)[:400]), flush=True)
        return rec

    def start(self, data):
        self.r.start()
        self.r.navigate(self.base + '/?sky=1&data=' + data)
        end = time.time() + 200
        while time.time() < end:
            if self.ev(READY, wait=False):
                break
            time.sleep(0.4)
        else:
            raise RuntimeError('readiness timeout for ' + data)
        time.sleep(4)

    def close(self):
        try:
            self.r.close()
        except Exception:
            pass


# ---------- DOM 探针：每一步都从 DOM 里读「对象当前身份」 ----------
def P(body):
    """body 以 return out; 结尾；这里只做 try/catch 包裹，不额外加 return。"""
    return '(()=>{ try { %s } catch(e){ return {probeError:String(e), stack:String(e&&e.stack).slice(0,300)}; } })()' % body


BASE = """
  var G=CLApp.graph(), S=window.CLSky, M=S.model(), D=window.CLSkyDeconstruction;
  var vis=function(e){ if(!e) return false; var b=e.getBoundingClientRect(), s=getComputedStyle(e);
    return b.width>2&&b.height>2&&s.visibility!=='hidden'&&s.display!=='none'&&e.offsetParent!==null; };
  var out={};
"""

# 解构面板当前聚焦对象
DECON_FOCUS = BASE + """
  out.mode = D && D.state ? D.state().mode : null;
  var panel=document.getElementById('skyDeconPanel');
  out.panelOpen = !!panel && !panel.hidden && vis(panel);
  var focus=panel?panel.querySelector('.sd-line.is-focus,.sd-event.is-focus,.sd-row.is-focus,[aria-selected=true][data-line-id]'):null;
  out.focusedLineId = focus?focus.getAttribute('data-line-id'):null;
  out.focusedLineTitle = focus?((focus.querySelector('.sd-line-name')||{}).textContent||'').trim():null;
  out.focusedLineObjective = focus?((focus.querySelector('.sd-line-objective')||{}).textContent||'').trim().slice(0,60):null;
  out.autoLineCount = panel?panel.querySelectorAll('.sd-line.is-auto').length:0;
  out.lineCount = panel?panel.querySelectorAll('.sd-line').length:0;
  out.visibleLineIds = panel?Array.prototype.slice.call(panel.querySelectorAll('.sd-line')).slice(0,12).map(function(b){return b.getAttribute('data-line-id')}):[];
  return out;
"""

# 星盘：当前聚焦/选中的节点
DISC = BASE + """
  var d=S.disc();
  out.plotOn = !!S.plot();
  out.discFocus = d&&d.desc?d.desc().focus:null;
  out.plotFocus = (function(){try{return S.state().focusLineId||S.state().focus||null}catch(e){return null}})();
  out.cursor = (function(){try{return S.state().cursor}catch(e){return null}})();
  out.eventId = (function(){try{return S.playerState().eventId}catch(e){return null}})();
  return out;
"""

# 罗盘
COMPASS = BASE + """
  var c=document.getElementById('skyCompass');
  out.compassOpen = !!c && !c.hidden && vis(c);
  out.compassIds = c?Array.prototype.slice.call(c.querySelectorAll('[data-line-id],[data-event-index],[data-t]')).slice(0,15)
      .map(function(b){return {a:b.getAttribute('data-line-id')||b.getAttribute('data-t')||b.getAttribute('data-event-index'),cls:String(b.className).slice(0,40)}}):[];
  out.compassText = c?(c.textContent||'').trim().slice(0,160):null;
  try{ out.focusLineId = S.state().focusLineId||null; }catch(e){}
  return out;
"""

# 原文
SOURCE = BASE + """
  ['skyStoryPanel','skyDeckBody','skyDeconPanel'].forEach(function(id){
    var e=document.getElementById(id); out['has_'+id]=!!e && !e.hidden && vis(e);
  });
  var sp=document.getElementById('skyStoryPanel');
  out.storyOpen = !!sp && !sp.hidden && vis(sp);
  if(sp){ out.storyText=(sp.textContent||'').trim().slice(0,200);
    out.storyEventId=(function(){try{return S.playerState().eventId}catch(e){return null}})(); }
  var q=document.querySelector('#skyStoryBody .ssp-quote,.ssp-quote,[data-quote]');
  out.quoteText=q?(q.textContent||'').trim().slice(0,160):null;
  out.eventId=(function(){try{return S.playerState().eventId}catch(e){return null}})();
  return out;
"""


def run_case(kind, base, out):
    c = CASES[kind]
    j = Journey(base, out)
    print('=== CASE %s · %s · %s' % (kind, c['note'], c['data']), flush=True)
    try:
        j.start(c['data'])
        # 00 入口基线
        j.step(0, 'entry', 'body', P(BASE + """
          out.title=G.title; out.chars=G.characters.length; out.events=G.events.length;
          out.storylines=G.storylines.length; out.tasks=(G.tasks||[]).length;
          out.mains=M.mains.length; out.lines=M.lines.length;
          out.autoMains=M.mains.filter(function(m){return m.autoSegment}).length;
          out.autoLines=M.lines.filter(function(l){return l.autoSegment}).length;
          out.withGoal=M.mains.filter(function(m){return m.taskGoalCount>0}).concat(M.lines.filter(function(l){return l.taskGoalCount>0})).length;
          out.objectIdsG=G.storylines.map(function(s){return String(s.id!=null?s.id:s.entityId)});
          out.objectIdsM=M.mains.map(function(m){return m.id}).concat(M.lines.map(function(l){return l.id}));
          return out;"""), '入口：数据层对象 id 基线')
        # 01 全书 → 解构面板（问题/线路在解构面板里）
        j.click('#skyDecode')
        time.sleep(1.2)
        j.step(1, 'deconstruct', '#skyDecode', P(DECON_FOCUS), '全书 → 解构面板（问题/线路）')
        # 切到「故事骨架」线路视图
        j.click('#skyDeconTabLines')
        time.sleep(1.0)
        j.step(2, 'lines-tab', '#skyDeconTabLines', P(DECON_FOCUS), '解构 → 故事骨架（线路列表）')
        # 选第一条线（或自动段）
        sel = '.sd-line.is-auto' if kind == 'auto' else '.sd-line'
        got = j.click(sel)
        time.sleep(1.2)
        j.step(3, 'line-focus', sel, P(DECON_FOCUS + """
          out.clicked = %s; out.chosenSelector=%s; return out;""" % ('true' if got else 'false', json.dumps(sel))),
               '点选线路 → focusLine')
        # 04 星盘（点线会 setPlot(true)）
        j.step(4, 'skychart', '.sd-line', P(DISC), '解构 → 星盘（聚焦线路）')
        # 05 罗盘
        op = j.click('#skyCompassOpen') or j.click('[data-sky="compass"]') or j.click('#skyDial')
        if not op:
            op = j.ev("(()=>{try{CLSky.openCompass();return true}catch(e){return String(e)}})()", wait=False)
        time.sleep(1.4)
        j.step(5, 'compass', '#skyCompassOpen' if op else '(api openCompass)', P(COMPASS), '星盘 → 罗盘')
        # 06 解构面板（从罗盘返回）
        j.ev("(()=>{try{CLSky.closeCompass();return true}catch(e){return String(e)}})()", wait=False)
        time.sleep(0.8)
        j.click('#skyDecode')
        time.sleep(1.0)
        j.step(6, 'decon-again', '#skyDecode', P(DECON_FOCUS), '罗盘 → 解构面板（同对象是否还是同一个）')
        # 07 原文
        j.ev("(()=>{try{CLSky.setPlot(true);CLSky.seekEventAt(0);return true}catch(e){return String(e)}})()", wait=False)
        time.sleep(1.6)
        j.step(7, 'source', 'CLSky.seekEventAt(0)', P(SOURCE), '解构 → 原文（事件/引文）')
        # 08 返回
        j.ev("(()=>{try{CLSky.stop();return true}catch(e){return String(e)}})()", wait=False)
        time.sleep(0.6)
        j.click('#skyDecode')
        time.sleep(0.8)
        j.step(8, 'return', '#skyDecode', P(BASE + """
          out.plotOn=!!S.plot(); out.eventId=S.playerState().eventId;
          try{out.focusLineId=S.state().focusLineId||null}catch(e){}
          var panel=document.getElementById('skyDeconPanel');
          out.panelOpen=!!panel&&!panel.hidden&&vis(panel);
          var f=panel?panel.querySelector('.sd-line.is-focus'):null;
          out.focusedLineId=f?f.getAttribute('data-line-id'):null;
          return out;"""), '原文 → 返回（对象守恒检查）')
    finally:
        (j.out / ('journey-%s.json' % kind)).write_text(
            json.dumps({'case': kind, 'note': c['note'], 'data': c['data'], 'steps': j.steps},
                       ensure_ascii=False, indent=2), encoding='utf-8')
        j.close()
    return j


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--base', default='http://127.0.0.1:8000')
    ap.add_argument('--case', default='auto')
    ap.add_argument('--out', default='/tmp/castline-shots/xgraph')
    a = ap.parse_args()
    kinds = list(CASES) if a.case == 'all' else [a.case]
    for k in kinds:
        try:
            run_case(k, a.base, a.out)
        except Exception as e:
            print('CASE %s ERROR %s' % (k, str(e)[:400]), flush=True)
            (Path(a.out) / ('ERROR-%s.txt' % k)).write_text(str(e), encoding='utf-8')
    return 0


if __name__ == '__main__':
    sys.exit(main())
